import os
import queue
import threading
from typing import Callable, Optional

from google.cloud import speech


class StreamingSpeechToText:
    def __init__(
        self,
        language_code: str = "en-US",
        sample_rate_hertz: int = 16000,
        encoding: speech.RecognitionConfig.AudioEncoding = speech.RecognitionConfig.AudioEncoding.LINEAR16,
    ):
        self.client = speech.SpeechClient()
        self.streaming_config = speech.StreamingRecognitionConfig(
            config=speech.RecognitionConfig(
                encoding=encoding,
                sample_rate_hertz=sample_rate_hertz,
                language_code=language_code,
            ),
            interim_results=True,
            single_utterance=False,
        )
        self._audio_queue: "queue.Queue[Optional[bytes]]" = queue.Queue()
        self._closed = threading.Event()

    def push_audio(self, chunk: bytes) -> None:
        if self._closed.is_set():
            raise RuntimeError("Stream is closed")
        self._audio_queue.put(chunk)

    def close(self) -> None:
        if not self._closed.is_set():
            self._closed.set()
            self._audio_queue.put(None)

    def _requests(self):
        yield speech.StreamingRecognizeRequest(streaming_config=self.streaming_config)
        while True:
            chunk = self._audio_queue.get()
            if chunk is None:
                return
            yield speech.StreamingRecognizeRequest(audio_content=chunk)

    def run(
        self,
        on_partial: Optional[Callable[[str], None]] = None,
        on_final: Optional[Callable[[str], None]] = None,
    ) -> None:
        for response in self.client.streaming_recognize(self._requests()):
            for result in response.results:
                if not result.alternatives:
                    continue
                transcript = result.alternatives[0].transcript.strip()
                if not transcript:
                    continue

                if result.is_final:
                    if on_final:
                        on_final(transcript)
                else:
                    if on_partial:
                        on_partial(transcript)


def main():
    language_code = os.getenv("GOOGLE_SPEECH_LANGUAGE_CODE", "en-US")
    sample_rate_hertz = int(os.getenv("GOOGLE_SPEECH_SAMPLE_RATE_HZ", "16000"))

    streamer = StreamingSpeechToText(
        language_code=language_code,
        sample_rate_hertz=sample_rate_hertz,
    )

    def print_partial(text: str) -> None:
        print(f"PARTIAL: {text}")

    def print_final(text: str) -> None:
        print(f"FINAL: {text}")

    try:
        streamer.run(on_partial=print_partial, on_final=print_final)
    except KeyboardInterrupt:
        streamer.close()


if __name__ == "__main__":
    main()
